	private final QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
	private final RestrictionLayout layout = new RestrictionLayout(List.of("s", "p", "o"), context);
	private final StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));

